use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_battery_evidence: Drone_Lifecycle_Governor::Battery_Evidence,
  pub api_decision_disposition: Drone_Lifecycle_Governor::Decision_Disposition
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_battery_evidence(container.api_battery_evidence);
  put_decision_disposition(container.api_decision_disposition);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  battery_evidence: Drone_Lifecycle_Governor::Battery_Evidence,
  decision_disposition: Drone_Lifecycle_Governor::Decision_Disposition)
{
  put_battery_evidence(battery_evidence);
  put_decision_disposition(decision_disposition);
}

/// setter for IN DataPort
pub fn put_battery_evidence(value: Drone_Lifecycle_Governor::Battery_Evidence)
{
  *extern_api::IN_battery_evidence.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_decision_disposition(value: Drone_Lifecycle_Governor::Decision_Disposition)
{
  *extern_api::IN_decision_disposition.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_pilot_notice() -> Drone_Lifecycle_Governor::Pilot_Notice
{
  return extern_api::OUT_pilot_notice.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
